/* preset: kami; schema: 43 */
:root {
  --paper: #faf6ef;
  --surface: #f3ede1;
  --surface-strong: #e9e0cf;
  --dark-surface: #2b2724;
  --deep-dark: #1c1916;
  --accent: #b0563b;
  --accent-on: #faf6ef;
  --ink: #2b2724;
  --text-primary: #3a352f;
  --text-secondary: #6b6258;
  --text-muted: #8d8478;
  --text-faint: #b3aa9c;
  --border: #d8cdb9;
  --border-soft: #e6ddcc;
  --font-sans: 'Noto Sans TC', sans-serif;
  --font-serif: 'Noto Serif TC', serif;
  --font-mono: 'JetBrains Mono', monospace;
  --shadow-ring: 0 0 0 1px rgba(43, 39, 36, 0.06);
  --shadow-whisper: 0 1px 2px rgba(43, 39, 36, 0.05);
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 40px;
  --space-2xl: 64px;
  --space-3xl: 96px;
  --radius-xs: 2px;
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;
  --radius-2xl: 24px;
  --radius-hero: 32px;
  --cover-title-align: left;
  --grid-columns: 12;
  --grid-gutter: 24px;
  --delta-up: #4a7c59;
  --delta-down: #a04b3c;
  --ease: cubic-bezier(0.4, 0, 0.2, 1);
  --duration: 200ms;
  --stagger-step: 60ms;
  --font-display: 'Noto Serif TC', serif;
  --shadow-drama: 0 24px 48px rgba(28, 25, 22, 0.18);
}

